//! The named parameters rakudo's `new` declares for each RakuAST class.
//!
//! `ctor_names.tsv` is generated by `scripts/rakuast-ctor-names.raku` from
//! rakudo 2026.09. A class listed there has an explicit `new` without a slurpy
//! hash, so a named argument outside its list is a bind failure in rakudo:
//! `Unexpected named argument 'x' passed`. A class without a row (`Mu.new`
//! takes `*%attrinit`) accepts any name.

use crate::value::{RuntimeError, Value, ValueView};
use std::collections::HashMap;
use std::sync::LazyLock;

static TABLE: LazyLock<HashMap<&'static str, Vec<&'static str>>> = LazyLock::new(|| {
    include_str!("ctor_names.tsv")
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .filter_map(|l| {
            let (class, names) = l.split_once('\t')?;
            Some((class, names.split(',').collect()))
        })
        .collect()
});

/// Names mutsu's constructors take that rakudo's `new` does not declare: the
/// documented model extensions (ADR-0088). `NamedCapture`'s `hash` is the `%`
/// alias sigil, which rakudo's RakuAST has no node for.
const EXTENSIONS: &[(&str, &str)] = &[("RakuAST::Regex::NamedCapture", "hash")];

/// Refuse the first named argument `class.new` does not declare.
// Cost: O(a * n), a = arguments, n = named parameters of the class; the first
// RakuAST constructor call builds the table once, O(r), r = rows in the file.
pub(super) fn check_new(class_name: &str, args: &[Value]) -> Result<(), RuntimeError> {
    if !class_name.starts_with("RakuAST::") || !args.iter().any(is_named) {
        return Ok(());
    }
    let Some(declared) = TABLE.get(class_name) else {
        return Ok(());
    };
    for arg in args {
        let name = match arg.view() {
            ValueView::Pair(key, _) => key.to_string(),
            ValueView::ValuePair(key, _) => key.to_string_value(),
            _ => continue,
        };
        if !declared.contains(&name.as_str())
            && !EXTENSIONS
                .iter()
                .any(|(class, extra)| *class == class_name && *extra == name)
        {
            return Err(RuntimeError::new(format!(
                "Unexpected named argument '{name}' passed"
            )));
        }
    }
    Ok(())
}

fn is_named(arg: &Value) -> bool {
    matches!(arg.view(), ValueView::Pair(..) | ValueView::ValuePair(..))
}

/// Whether `class_name.new` declares the named parameter `name`.
// Cost: O(n), n = named parameters of the class.
pub(super) fn declares(class_name: &str, name: &str) -> bool {
    class_name.starts_with("RakuAST::")
        && TABLE
            .get(class_name)
            .is_some_and(|declared| declared.contains(&name))
}
